static class ControlAndCountdownTests {
 const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static object Get(object o,string name){return o.GetType().GetField(name,Flags).GetValue(o);}
 static void Put(object o,string name,object value){o.GetType().GetField(name,Flags).SetValue(o,value);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Flags).Invoke(o,args);}
 sealed class Sender:IVideoSender {public void Send(byte[] p,int w,int h,int f){Thread.Sleep(10);}public void Dispose(){}}
 sealed class Timed:IFrameSource,IPlaybackSource {public bool Disposed;public VideoPlaybackStatus Status;readonly byte[] frame=new byte[1024];public Timed(){frame[3]=255;Status=VideoPlaybackStatus.FromFrames("movie.mov",20,51,10,true,false);}public string Error{get{return null;}}public byte[] ReadFrame(){return frame;}public byte[] ReadPlaybackFrame(out VideoPlaybackStatus status){status=Status.Copy();return frame;}public void Dispose(){Disposed=true;}}
 static T Pump<T>(Task<T> task){var until=DateTime.UtcNow.AddSeconds(12);while(!task.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(2);}if(!task.IsCompleted)throw new Exception("Timeout test TCP/UI");return task.GetAwaiter().GetResult();}
 static string[] Send(int port,params string[] lines){return Pump(Task.Run(()=>{using(var client=new TcpClient("127.0.0.1",port)){client.ReceiveTimeout=8000;using(var stream=client.GetStream())using(var reader=new StreamReader(stream,Encoding.UTF8)){var results=new List<string>();foreach(string line in lines){byte[] bytes=Encoding.ASCII.GetBytes(line+"\n");stream.Write(bytes,0,bytes.Length);results.Add(reader.ReadLine());}return results.ToArray();}}}));}
 static void Wait(Func<bool> condition){var until=DateTime.UtcNow.AddSeconds(3);while(!condition()&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(5);}if(!condition())throw new Exception("Condizione Program non raggiunta");}
 public static void Run(Action<bool,string> check){
  var start=VideoPlaybackStatus.FromFrames("a.mov",12,1,25,false,false);check(Math.Abs(start.Remaining-12)<.001&&start.Display().Contains("00:12.0"),"countdown parte dalla durata del video");
  var loop=VideoPlaybackStatus.FromFrames("a.mov",12,326,25,true,false);check(Math.Abs(loop.Position-1)<.001&&loop.Display().Contains("Al prossimo loop: 00:11.0"),"countdown riparte correttamente al giro successivo");
  var end=VideoPlaybackStatus.FromFrames("a.mov",12,300,25,false,true);check(end.Remaining==0&&end.Display().StartsWith("Video terminato"),"countdown senza loop termina a zero");
  check(VideoPlaybackStatus.FromFrames("a",0,1,25,false,false).Display().Contains("non disponibile"),"durata sconosciuta non produce un countdown inventato");
  check(VideoPlaybackStatus.FromFrames("a",3661.2,1,25,false,false).Display().Contains("01:01:01.2"),"countdown supporta video oltre un'ora");
  check(VideoPlaybackStatus.FromFrames("a",Double.NaN,1,25,false,false).Display().Contains("non disponibile"),"metadati di durata non validi non causano eccezioni UI");
  check(!VideoPlaybackStatus.FromFrames("a",12,0,25,false,false).Ready,"countdown distingue avvio da fotogrammi decodificati");
  using(var pgm=new Playout(new Sender(),16,16,50)){var source=new Timed();pgm.CueSource(source,source.ReadFrame(),0,"movie.mov");Wait(()=>pgm.ReadSentPlayback()!=null);var saved=pgm.ReadSentPlayback();saved.Position=999;check(pgm.ReadSentPlayback().Position==5,"monitor countdown conserva snapshot isolato del frame inviato");pgm.Cue(new byte[1024],.3);Wait(()=>pgm.ReadOnAirStatus().Transitioning);check(pgm.ReadSentPlayback()!=null&&!source.Disposed,"countdown e decoder restano attivi durante clear in dissolvenza");Wait(()=>pgm.ReadOnAirStatus().Paths.Length==0);check(pgm.ReadSentPlayback()==null&&source.Disposed,"clear completato rimuove countdown e decoder");}
  CompanionCommand parsed;check(CompanionCommand.TryParse(" select 0012 ",out parsed)&&parsed.Value=="0012","parser TCP accetta numero e maiuscole/minuscole");check(!CompanionCommand.TryParse("GO 12",out parsed)&&!CompanionCommand.TryParse("DIGIT 12",out parsed)&&!CompanionCommand.TryParse("SELECT -1",out parsed),"parser rifiuta argomenti non validi senza eseguire comandi");
  var received=new List<string>();using(var server=new CompanionControlServer(IPAddress.Loopback,0,line=>{lock(received)received.Add(line);return "OK "+line;})){
   var result=Pump(Task.Run(()=>{using(var client=new TcpClient("127.0.0.1",server.Port)){client.ReceiveTimeout=3000;using(var stream=client.GetStream())using(var reader=new StreamReader(stream)){var a=Encoding.ASCII.GetBytes("NE");stream.Write(a,0,a.Length);Thread.Sleep(30);a=Encoding.ASCII.GetBytes("XT\r\nPREV\n");stream.Write(a,0,a.Length);return new[]{reader.ReadLine(),reader.ReadLine()};}}}));check(result.SequenceEqual(new[]{"OK NEXT","OK PREV"})&&received.SequenceEqual(new[]{"NEXT","PREV"}),"TCP ricompone pacchetti frammentati e comandi multipli LF/CRLF");
   result=Send(server.Port,new String('X',200),"GO");check(result[0].StartsWith("ERR")&&result[1]=="OK GO","linea TCP eccessiva viene scartata e la connessione resta utilizzabile");
  }
  string dir=Path.Combine(Path.GetTempPath(),"ndi-controls-"+Guid.NewGuid());Directory.CreateDirectory(dir);
  try{
   string a=Path.Combine(dir,"zeta.png"),b=Path.Combine(dir,"alfa.png"),c=Path.Combine(dir,"beta.png");foreach(string file in new[]{a,b,c})using(var image=new Bitmap(8,8)){using(var g=Graphics.FromImage(image))g.Clear(Color.Coral);image.Save(file);}
   using(var browser=new LibraryBrowser()){var handle=browser.Handle;var list=browser.Controls.OfType<ListView>().Single();var h=list.Handle;browser.SetNumbers(new Dictionary<string,string>{{a,"10"},{b,"2"},{c,"001"}});browser.SetFiles(new List<string>{a,b,c});browser.SetPreferences(true,128);browser.SelectPaths(new[]{b});check(browser.NavigateKey(Keys.Right)&&browser.SelectedPath==c,"freccia destra percorre tutte le miniature in ordine lineare");check(browser.NavigateKey(Keys.Right)&&browser.SelectedPath==c,"ultima miniatura non ricomincia dalla prima");browser.NavigateKey(Keys.Left);check(browser.SelectedPath==b,"freccia sinistra torna alla miniatura precedente");browser.SortByColumn(1);check(browser.PathsInView.SequenceEqual(new[]{c,b,a}),"ordinamento numerico considera 1, 2 e 10");browser.SortByColumn(1);check(browser.PathsInView.SequenceEqual(new[]{a,b,c}),"secondo clic inverte ordinamento numerico");browser.SortByColumn(0);check(browser.PathsInView.SequenceEqual(new[]{b,c,a})&&browser.SelectedPath==b,"ordinamento nome conserva la selezione");browser.RestoreManualOrder();check(browser.PathsInView.SequenceEqual(new[]{a,b,c})&&!browser.Sorted,"ordine manuale ripristina la playlist originale");browser.SortByColumn(2);check(browser.PathsInView.Last()==b,"ordinamento Stato usa lo stato selezionato al momento del clic");browser.SortByColumn(3);check(browser.PathsInView.SequenceEqual(new[]{b,c,a}),"ordinamento Percorso segue il percorso completo");browser.SetNumbers(new Dictionary<string,string>{{a,"10"},{b,"2"}});browser.SortByColumn(1);check(browser.PathsInView.SequenceEqual(new[]{b,a,c}),"file senza numero restano in fondo");browser.SortByColumn(1);check(browser.PathsInView.SequenceEqual(new[]{a,b,c}),"file senza numero restano in fondo anche in ordine decrescente");browser.RestoreManualOrder();
    var grid=Enumerable.Range(0,9).Select(i=>Path.Combine(dir,"grid-"+i+".png")).ToList();browser.Size=new Size(350,400);browser.SetPreferences(true,64);browser.SetFiles(grid);int edge=-1;for(int i=0;i<8;i++)if(list.GetItemRect(i+1).Top>list.GetItemRect(i).Top){edge=i;break;}check(edge>=0,"griglia test dispone miniature su più righe");browser.SelectPaths(new[]{grid[edge]});var message=Message.Create(list.Handle,0x100,(IntPtr)Keys.Right,IntPtr.Zero);var arguments=new object[]{message,Keys.Right};bool handled=(bool)list.GetType().GetMethod("ProcessCmdKey",Flags).Invoke(list,arguments);check(handled&&browser.SelectedPath==grid[edge+1],"tasto destro reale passa dall'ultima colonna alla riga successiva");arguments=new object[]{message,Keys.Left};handled=(bool)list.GetType().GetMethod("ProcessCmdKey",Flags).Invoke(list,arguments);check(handled&&browser.SelectedPath==grid[edge],"tasto sinistro reale passa alla riga precedente");}
   var data=new Settings{Root=dir,OutputWidth=16,OutputHeight=16,OutputFps=50};var first=ProjectStore.AddBlock(data,"Uno");var second=ProjectStore.AddBlock(data,"Due");ProjectStore.AddFiles(first,new[]{a,b,c});ProjectStore.AddFiles(second,new[]{a,c});ProjectStore.Normalize(data);first.Numbers[a]="1";first.Numbers[b]="2";first.Numbers[c]="10";second.Numbers[a]="12";second.Numbers[c]="1";data.ActiveBlockId=first.Id;
   using(var reserved=new TcpListenerScope()){data.Companion.ControlPort=reserved.Port;}data.Companion.ControlEnabled=true;data.Companion.ControlAddress="127.0.0.1";string prefs=Path.Combine(dir,"prefs.json");File.WriteAllText(prefs,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(data));
   using(var window=new MainWindow(prefs)){window.ShowInTaskbar=false;window.StartPosition=FormStartPosition.Manual;window.Location=new Point(-3000,-3000);window.Show();Application.DoEvents();var browser=(LibraryBrowser)Get(window,"files");var pgm=new Playout(new Sender(),16,16,50);Put(window,"output",pgm);Put(window,"outW",16);Put(window,"outH",16);Put(window,"activeProgramFps",50);pgm.Cue(Renderer.Render(a,16,16,new Placement()),0,a);Wait(()=>pgm.ReadOnAirStatus().Paths.Contains(a));var listener=(CompanionControlServer)Get(window,"controlServer");int port=listener.Port;
    var controlStatus=(Label)Get(window,"controlStatus");check(controlStatus.Text.Contains("senza autenticazione")&&controlStatus.Text.Contains("rete protetta"),"avviso TCP visibile anche all'avvio con configurazione salvata");
    var focus=(TextBox)Get(window,"search");focus.Focus();var replies=Send(port,"NEXT");check(replies[0]=="OK NEXT"&&browser.SelectedPath==b&&pgm.ReadOnAirStatus().Paths.SequenceEqual(new[]{a}),"NEXT TCP prepara solo Preview senza alterare Program");check(focus.Focused,"comandi TCP funzionano senza focus sulla libreria e non lo spostano");
    check(Send(port,"SELECT 10")[0]=="OK SELECT 10"&&browser.SelectedPath==c,"SELECT TCP richiama numero nel blocco attivo");check(Send(port,"GO")[0]=="OK GO","GO TCP accetta selezione valida");Wait(()=>pgm.ReadOnAirStatus().Paths.SequenceEqual(new[]{c}));
    replies=Send(port,"SELECT 999","GO");check(replies.All(x=>x.StartsWith("ERR"))&&pgm.ReadOnAirStatus().Paths.SequenceEqual(new[]{c}),"numero assente blocca GO evitando invio di selezione precedente");Send(port,"CANCEL");
    replies=Send(port,"NEXT_BLOCK");check(replies[0]=="OK BLOCK Due"&&browser.SelectedPath==a&&pgm.ReadOnAirStatus().Paths.SequenceEqual(new[]{c}),"cambio blocco TCP seleziona primo file senza cambiare Program");
    replies=Send(port,"DIGIT 1","DIGIT 2");check(replies.Last()=="OK NUMBER 12"&&browser.SelectedPath==a,"tastierino Companion compone numero separato dalla selezione");check(Send(port,"GO")[0].StartsWith("ERR"),"GO non invia se il numero composto non è confermato");replies=Send(port,"ENTER","GO");check(replies[0]=="OK SELECT 12"&&replies[1]=="OK GO","ENTER seleziona e GO invia con numerazione indipendente per blocco");Wait(()=>pgm.ReadOnAirStatus().Paths.SequenceEqual(new[]{a}));
    replies=Send(port,"DIGIT 9","DIGIT 8","BACKSPACE","CANCEL");check(replies[2]=="OK NUMBER 9"&&replies[3]=="OK CANCEL","BACKSPACE e CANCEL correggono il numero remoto");
    ((NumericUpDown)Get(window,"escClearFade")).Value=1200;check(Send(port,"CLEAR_FADE")[0]=="OK CLEAR_FADE"&&pgm.Clearing,"CLEAR_FADE TCP usa la dissolvenza dedicata anche con cambio foto in cut");check(Send(port,"CLEAR_CUT")[0]=="OK CLEAR_CUT","CLEAR_CUT interrompe immediatamente la dissolvenza");Wait(()=>pgm.ReadOnAirStatus().Paths.Length==0);check(browser.SelectedPath==a&&Get(window,"output")!=null,"clear remoto lascia Preview e canale NDI invariati");
    replies=Send(port,"PREV_BLOCK","PREV_BLOCK");check(replies[0]=="OK BLOCK Uno"&&replies[1].StartsWith("ERR"),"PREV_BLOCK torna al precedente e si ferma al primo blocco");
    var timed=new Timed();pgm.CueSource(timed,timed.ReadFrame(),0,"movie.mov");Wait(()=>pgm.ReadSentPlayback()!=null);Send(port,"NEXT");Call(window,"UpdateProgramCountdown");check(((Control)Get(window,"programCountdown")).Text.Contains("Al prossimo loop: 00:15.0"),"countdown segue Program anche dopo cambio selezione in Preview");
    var current=(Settings)Get(window,"settings");check(current.Blocks[0].Files.SequenceEqual(new[]{a,b,c}),"navigazione e richiami non riscrivono playlist");string project=Path.Combine(dir,"show.ndiproj");ProjectStore.Write(project,current);var loaded=ProjectStore.Read(project);check(loaded.Companion.ControlEnabled&&loaded.Companion.ControlPort==port&&loaded.Companion.Copy().ControlAddress=="127.0.0.1","progetto e copia configurazione conservano ricezione TCP separata");current.Companion.ControlEnabled=false;Call(window,"ApplyCompanionControl");check(controlStatus.Text=="Comandi TCP: spenti","avviso TCP rimosso quando la ricezione viene disattivata");
   }
  }finally{Directory.Delete(dir,true);}
 }
 sealed class TcpListenerScope:IDisposable {readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);public int Port{get{return ((IPEndPoint)listener.LocalEndpoint).Port;}}public TcpListenerScope(){listener.Start();}public void Dispose(){listener.Stop();}}
